1	/**
2	 * Idempotent seed (content-model section 6; REQ-01.34, REQ-02.33, REQ-03.15, REQ-01.2, AC-01.11).
3	 *
4	 * Runs on every bootstrap. It only creates what does not exist yet and never overwrites
5	 * what the business may have changed in the admin:
6	 *   - country           → looked up by `code`;
7	 *   - form-field        → looked up by `key` (globally unique, country prefix, G3-4);
8	 *   - plan              → looked up by `name` within the country;
9	 *   - country-selection → single type, created only if it has no document.
10	 *
11	 * Lookups use the draft version (Document Service default): in Strapi 5 every document
12	 * keeps a draft version, published or not, so a document is found whatever its state.
13	 * Items flagged `publish: false` are created as drafts and never published.
14	 */
15	import type { Core } from '@strapi/strapi';
16	import { co } from './data/co';
17	import { cl } from './data/cl';
18	import { countrySelection } from './data/country-selection';
19	
20	// ---------- Seed data types (mirror content-model sections 2 and 3) ----------
21	
22	type BlockText = { type: 'text'; text: string; bold?: boolean; italic?: boolean };
23	type BlockListItem = { type: 'list-item'; children: BlockText[] };
24	type Block =
25	  | { type: 'paragraph'; children: BlockText[] }
26	  | { type: 'list'; format: 'ordered' | 'unordered'; children: BlockListItem[] };
27	
28	export interface PriceFactorSeed {
29	  role: 'vehicleYear' | 'birthDate';
30	  operand: 'vehicleAge' | 'ageInYears';
31	  min: number | null;
32	  max: number | null;
33	  multiplier: number;
34	}
35	
36	export interface CountryDataSeed {
37	  code: string;
38	  name: string;
39	  intlLocale: string;
40	  currency: string;
41	  minimumAge: number;
42	  wizardTexts: Record<string, string>;
43	  formStepTexts: Record<string, string>;
44	  plansStepTexts: Record<string, string>;
45	  summaryStepTexts: Record<string, string>;
46	  confirmationTexts: Record<string, string>;
47	  priceFactors: PriceFactorSeed[];
48	  termsAndConditions: Block[];
49	}
50	
51	type ValidationRuleSeed =
52	  | { kind: 'minLength' | 'maxLength' | 'min' | 'max'; value: number }
53	  | { kind: 'pattern'; pattern: string }
54	  | { kind: 'integer' };
55	
56	export interface FormFieldSeed {
57	  publish: boolean;
58	  key: string;
59	  label: string;
60	  type: 'text' | 'number' | 'select' | 'date' | 'checkbox';
61	  required: boolean;
62	  helpText?: string;
63	  errorMessage?: string;
64	  order?: number;
65	  section: 'policyholder' | 'vehicle';
66	  role?: 'documentNumber' | 'birthDate' | 'vehicleYear';
67	  options?: { value: string; label: string }[];
68	  validations?: ValidationRuleSeed[];
69	}
70	
71	export interface PlanSeed {
72	  publish: boolean;
73	  name: string;
74	  shortDescription?: string;
75	  basePrice: number;
76	  currency: string;
77	  order?: number;
78	  recommended: boolean;
79	  active: boolean;
80	  coverages: { label: string }[];
81	  benefits: { label: string }[];
82	}
83	
84	export interface CountrySeed {
85	  country: CountryDataSeed;
86	  formFields: FormFieldSeed[];
87	  plans: PlanSeed[];
88	}
89	
90	export interface CountrySelectionSeed {
91	  heading: string;
92	  intro: string;
93	  countryListLabel: string;
94	}
95	
96	// ---------- Implementation ----------
97	
98	const COUNTRY = 'api::country.country';
99	const FORM_FIELD = 'api::form-field.form-field';
100	const PLAN = 'api::plan.plan';
101	const COUNTRY_SELECTION = 'api::country-selection.country-selection';
102	
103	interface Counters {
104	  created: number;
105	  existing: number;
106	}
107	
108	const log = (strapi: Core.Strapi, message: string) => strapi.log.info(`[seed] ${message}`);
109	
110	async function seedCountry(strapi: Core.Strapi, seed: CountrySeed, counters: Counters) {
111	  const countries = strapi.documents(COUNTRY);
112	  const { code } = seed.country;
113	
114	  let country = await countries.findFirst({ filters: { code } });
115	  if (country) {
116	    counters.existing += 1;
117	    log(strapi, `country ${code}: exists (documentId ${country.documentId}), not modified`);
118	  } else {
119	    country = await countries.create({ data: seed.country });
120	    await countries.publish({ documentId: country.documentId });
121	    counters.created += 1;
122	    log(strapi, `country ${code}: created and published (documentId ${country.documentId})`);
123	  }
124	
125	  const fields = strapi.documents(FORM_FIELD);
126	  for (const { publish, ...field } of seed.formFields) {
127	    const found = await fields.findFirst({ filters: { key: field.key } });
128	    if (found) {
129	      counters.existing += 1;
130	      continue;
131	    }
132	    const created = await fields.create({ data: { ...field, country: country.documentId } });
133	    if (publish) {
134	      await fields.publish({ documentId: created.documentId });
135	    }
136	    counters.created += 1;
137	    log(strapi, `form-field ${field.key}: created (${publish ? 'published' : 'draft only'})`);
138	  }
139	
140	  const plans = strapi.documents(PLAN);
141	  for (const { publish, ...plan } of seed.plans) {
142	    const found = await plans.findFirst({ filters: { name: plan.name, country: { code } } });
143	    if (found) {
144	      counters.existing += 1;
145	      continue;
146	    }
147	    const created = await plans.create({ data: { ...plan, country: country.documentId } });
148	    if (publish) {
149	      await plans.publish({ documentId: created.documentId });
150	    }
151	    counters.created += 1;
152	    log(
153	      strapi,
154	      `plan ${code}/"${plan.name}": created (${publish ? 'published' : 'draft only'}, active=${plan.active})`,
155	    );
156	  }
157	}
158	
159	async function seedCountrySelection(strapi: Core.Strapi, counters: Counters) {
160	  const selection = strapi.documents(COUNTRY_SELECTION);
161	  const found = await selection.findFirst();
162	  if (found) {
163	    counters.existing += 1;
164	    log(strapi, 'country-selection: exists, not modified');
165	    return;
166	  }
167	  const created = await selection.create({ data: countrySelection });
168	  await selection.publish({ documentId: created.documentId });
169	  counters.created += 1;
170	  log(strapi, 'country-selection: created and published');
171	}
172	
173	export async function runSeed(strapi: Core.Strapi): Promise<void> {
174	  const counters: Counters = { created: 0, existing: 0 };
175	  for (const seed of [co, cl]) {
176	    await seedCountry(strapi, seed, counters);
177	  }
178	  await seedCountrySelection(strapi, counters);
179	  log(strapi, `done: ${counters.created} created, ${counters.existing} already present (left untouched)`);
180	}
