1	/**
2	 * Public role permissions (content-model section 4, ADR-0003 section 1, D4 refined by G3-2).
3	 *
4	 * Applied on every bootstrap, idempotently: after it runs the public role has EXACTLY the
5	 * permissions below and nothing else; the authenticated role has none; sign-ups are disabled.
6	 * Any permission added by hand in the admin is revoked on the next start (by design).
7	 *
8	 * Only `find`, no `findOne`: no read in api-contracts needs it (the chosen plan is checked
9	 * against the list, REQ-03.14). No upload, users-permissions (auth/user/role) or i18n permissions.
10	 */
11	import type { Core } from '@strapi/strapi';
12	
13	export const PUBLIC_PERMISSIONS: ReadonlyArray<{ action: string; reason: string }> = [
14	  {
15	    action: 'api::country.country.find',
16	    reason: 'Country list, country config, price factors and terms (api-contracts C1, C3, C6, C7)',
17	  },
18	  { action: 'api::form-field.form-field.find', reason: 'Step 1 fields of the country (C4)' },
19	  { action: 'api::plan.plan.find', reason: 'Plans of the country for step 2 and summary (C5)' },
20	  { action: 'api::country-selection.country-selection.find', reason: 'Texts of the / page (C2)' },
21	];
22	
23	const ROLE = 'plugin::users-permissions.role';
24	const PERMISSION = 'plugin::users-permissions.permission';
25	
26	const log = (strapi: Core.Strapi, message: string) => strapi.log.info(`[permissions] ${message}`);
27	
28	async function findRole(strapi: Core.Strapi, type: 'public' | 'authenticated') {
29	  const role = await strapi.db.query(ROLE).findOne({ where: { type } });
30	  if (!role) {
31	    throw new Error(`[permissions] users-permissions role "${type}" not found`);
32	  }
33	  return role as { id: number };
34	}
35	
36	async function permissionsOf(strapi: Core.Strapi, roleId: number) {
37	  return (await strapi.db.query(PERMISSION).findMany({ where: { role: { id: roleId } } })) as Array<{
38	    id: number;
39	    action: string;
40	  }>;
41	}
42	
43	export async function applyPublicPermissions(strapi: Core.Strapi): Promise<void> {
44	  const allowed = new Set(PUBLIC_PERMISSIONS.map((p) => p.action));
45	
46	  // Public role: grant the allowlist, revoke everything else.
47	  const publicRole = await findRole(strapi, 'public');
48	  const current = await permissionsOf(strapi, publicRole.id);
49	  const revoked: string[] = [];
50	  const kept = new Set<string>();
51	  for (const permission of current) {
52	    if (allowed.has(permission.action) && !kept.has(permission.action)) {
53	      kept.add(permission.action);
54	    } else {
55	      await strapi.db.query(PERMISSION).delete({ where: { id: permission.id } });
56	      revoked.push(permission.action);
57	    }
58	  }
59	  const granted: string[] = [];
60	  for (const action of allowed) {
61	    if (!kept.has(action)) {
62	      await strapi.db.query(PERMISSION).create({ data: { action, role: publicRole.id } });
63	      granted.push(action);
64	    }
65	  }
66	
67	  // Authenticated role: no permissions (content-model section 4).
68	  const authenticatedRole = await findRole(strapi, 'authenticated');
69	  const authenticatedRevoked: string[] = [];
70	  for (const permission of await permissionsOf(strapi, authenticatedRole.id)) {
71	    await strapi.db.query(PERMISSION).delete({ where: { id: permission.id } });
72	    authenticatedRevoked.push(permission.action);
73	  }
74	
75	  // "Enable sign-ups" = false (ADR-0003 section 1).
76	  const store = strapi.store({ type: 'plugin', name: 'users-permissions' });
77	  const advanced = ((await store.get({ key: 'advanced' })) ?? {}) as Record<string, unknown>;
78	  if (advanced.allow_register !== false) {
79	    await store.set({ key: 'advanced', value: { ...advanced, allow_register: false } });
80	    log(strapi, 'sign-ups disabled (allow_register=false)');
81	  }
82	
83	  log(strapi, `public: granted [${granted.join(', ')}], revoked [${revoked.join(', ')}]`);
84	  log(strapi, `authenticated: revoked [${authenticatedRevoked.join(', ')}]`);
85	  const final = (await permissionsOf(strapi, publicRole.id)).map((p) => p.action).sort();
86	  log(strapi, `public role now has exactly: [${final.join(', ')}]`);
87	}
